def kleene(L, n):
    """L dilinin n uzunluguna kadar olan Kleene yildizi elemanlari."""
    out = {""}
    frontier = {""}
    for _ in range(n):
        yeni = set()
        for u in frontier:
            for v in L:
                if len(u) + len(v) <= n:
                    yeni.add(u + v)
        frontier = yeni - out
        out |= yeni
    return out

