# Vize tekrari: bir DFA'nin dilinin BOS olup olmadigina karar ver (erisilebilirlik)
def bos_mu(delta, q0, F, sigma):
    gorulen, yigin = {q0}, [q0]
    while yigin:
        q = yigin.pop()
        for ch in sigma:
            r = delta[(q, ch)]
            if r not in gorulen:
                gorulen.add(r)
                yigin.append(r)
    return not (gorulen & F)

