# Belirsizlik: bir dizgi icin kac farkli turetme agaci var?
# Gramer:  E -> E + E | E * E | ( E ) | id
def agac_sayisi(tokenlar):
    bellek = {}
    def f(i, j):
        if (i, j) in bellek:
            return bellek[(i, j)]
        if j - i == 1:
            r = 1 if tokenlar[i] == "id" else 0
        else:
            r = 0
            for k in range(i + 1, j - 1):
                if tokenlar[k] in "+*":
                    r += f(i, k) * f(k + 1, j)
            if tokenlar[i] == "(" and tokenlar[j - 1] == ")":
                r += f(i + 1, j - 1)
        bellek[(i, j)] = r
        return r
    return f(0, len(tokenlar))

