# PDA simulasyonu: L = {a^n b^n | n >= 0}, yigin izini yazdir
def pda(w):
    yigin, durum, i = ["Z0"], "q0", 0
    print(f"  baslangic: ({durum}, {w or 'eps'}, {''.join(reversed(yigin))})")
    while i < len(w):
        ch = w[i]
        if durum == "q0" and ch == "a":
            yigin.append("A"); i += 1
        elif durum == "q0" and ch == "b":
            durum = "q1"; continue          # epsilon-gecis, girdi tuketilmez
        elif durum == "q1" and ch == "b" and yigin[-1] == "A":
            yigin.pop(); i += 1
        else:
            print("  RED (gecis yok)"); return False
        print(f"  ({durum}, {w[i:] or 'eps'}, {''.join(reversed(yigin))})")
    if durum == "q0":
        durum = "q1"
    ok = yigin == ["Z0"]
    print("  KABUL" if ok else "  RED (yigin bos degil)")
    return ok

for w in ["aabb", "aab"]:
