# CYK algoritmasi: O(n^3 |G|) -- CNF gramer zorunlu
birim = {"a": {"A", "C"}, "b": {"B"}}
ikili = {("A","B"): {"S","C"}, ("B","C"): {"S"}, ("B","A"): {"A"}, ("C","C"): {"B"}}

def cyk(w, baslangic="S"):
    n = len(w)
    T = [[set() for _ in range(n)] for _ in range(n + 1)]
    for i, ch in enumerate(w):
        T[1][i] = set(birim.get(ch, ()))
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            for k in range(1, l):
                for B in T[k][i]:
                    for C in T[l - k][i + k]:
                        T[l][i] |= ikili.get((B, C), set())
    for l in range(n, 0, -1):
        satir = ["{" + ",".join(sorted(T[l][i])) + "}" if T[l][i] else "-"
                 for i in range(n - l + 1)]
        print(f"l={l}: " + " ".join(s.ljust(8) for s in satir))
    return baslangic in T[n][0]

print("baaba in L(G)?", cyk("baaba"))

