# Turing makinesi simulatoru: L = {0^n 1^n | n >= 1}
# Serit: liste, B = bos sembol. delta[(durum, okunan)] = (yeni durum, yazilan, yon)
delta = {
    ("q0","0"): ("q1","X","R"),
    ("q1","0"): ("q1","0","R"), ("q1","Y"): ("q1","Y","R"),
    ("q1","1"): ("q2","Y","L"),
    ("q2","0"): ("q2","0","L"), ("q2","Y"): ("q2","Y","L"),
    ("q2","X"): ("q0","X","R"),
    ("q0","Y"): ("q3","Y","R"),
    ("q3","Y"): ("q3","Y","R"), ("q3","B"): ("qk","B","R"),
}
def tm(w, adim_yaz=False):
    serit = list(w) + ["B"] * 4
    durum, kafa, adim = "q0", 0, 0
    while durum != "qk":
        okunan = serit[kafa] if kafa < len(serit) else "B"
        if (durum, okunan) not in delta:
            return "RED", adim
        durum, yaz, yon = delta[(durum, okunan)]
        serit[kafa] = yaz
        kafa += 1 if yon == "R" else -1
        adim += 1
        if kafa < 0:
            return "RED", adim
        if adim > 200:
            return "DONMEDI", adim
    return "KABUL", adim

for w in ["01", "0011", "001", "0101", "000111"]:
    print(f"{w:8} {tm(w)}")
